import csv, io, zipfile, collections, json

zip_path = r"Z:\Магистратура\Семестр 3\AgentSlop\MLOps_New\data\motor_data14-2018.zip"
z = zipfile.ZipFile(zip_path)
name = z.namelist()[0]
cat_cols = ["SEX", "INSR_TYPE", "TYPE_VEHICLE", "MAKE", "USAGE"]
num_cols = ["INSURED_VALUE", "PREMIUM", "PROD_YEAR", "SEATS_NUM", "CARRYING_CAPACITY"]
res = {"date_samples": [], "cards": {}, "negatives": {}, "ranges": {}, "truck_rows": 0, "n": 0,
       "dtypes_guess": {}}
vals = {c: collections.Counter() for c in cat_cols}
with z.open(name) as fh:
    txt = io.TextIOWrapper(fh, encoding="utf-8", errors="replace")
    rdr = csv.reader(txt)
    hdr = next(rdr)
    idx = {c: i for i, c in enumerate(hdr)}
    for k, row in enumerate(rdr):
        if not row:
            continue
        res["n"] += 1
        if k < 200000 and len(res["date_samples"]) < 8 and k % 40000 == 0:
            res["date_samples"].append(row[idx["INSR_BEGIN"]] + " | END=" + row[idx["INSR_END"]])
        for c in cat_cols:
            vals[c][row[idx[c]]] += 1
        for c in num_cols:
