                res["negatives"].setdefault(c, "NONDUMERIC:" + v)
                continue
            if f < 0:
                res["negatives"][c] = res["negatives"].get(c, 0) + 1
            r = res["ranges"].setdefault(c, [f, f])
            r[0] = min(r[0], f)
            r[1] = max(r[1], f)
        if row[idx["TYPE_VEHICLE"]].strip().lower() == "truck":
            res["truck_rows"] += 1
