"""Загрузка, валидация и разрешение конфигурации (АР-1).

Конфигурация — единственный источник истины: ни пути, ни пороги, ни
гиперпараметры не должны быть зашиты в коде. Модуль отвечает за:

* чтение и валидацию `config.yaml` по схеме с понятными сообщениями об ошибках;
* разрешение относительных путей относительно корня проекта;
* вычисление хэша конфигурации (`config_hash`) для прослеживаемости артефактов (АР-6).

Конфигурация загружается один раз при старте и передаётся дальше явно
(АР-13: никаких `load_config()` в горячих местах и на уровне модулей).
"""

from __future__ import annotations

import copy
import hashlib
import json
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import yaml

DEFAULT_CONFIG_NAME = "config.yaml"

#: Ключи верхнего уровня, обязательные для работы конвейера.
REQUIRED_SECTIONS = (
    "paths",
    "batching",
    "features",
    "target",
    "quality",
    "preprocessing",
    "models",
    "validation",
)

VALID_OPERATORS = (
    "eq", "ne", "ge", "gt", "le", "lt",
    "between", "not_between", "in", "not_in",
    "notna", "isna", "positive", "non_negative",
)

NUMERIC_OPERATORS = ("ge", "gt", "le", "lt", "between", "not_between", "positive", "non_negative")
SEVERITIES = ("error", "warn")


class ConfigError(ValueError):
    """Некорректный или неполный конфигурационный файл."""


@dataclass(frozen=True)
class Config:
    """Неизменяемая обёртка над словарём конфигурации.

    Хранит проверенные данные, корень проекта и хэш конфигурации. Все
    обращения идут через словарь (`cfg["quality"]`), а готовые подразделы
    доступны как свойства, чтобы не размазывать строковые ключи по коду.
    """

    data: dict[str, Any]
    root: Path

    # -- доступ к данным -------------------------------------------------

    def __getitem__(self, key: str) -> Any:
        return self.data[key]

    def get(self, key: str, default: Any = None) -> Any:
        return self.data.get(key, default)

    # -- разделы, которые нужны почти всегда ----------------------------

    @property
    def paths(self) -> dict[str, Any]:
        return self.data["paths"]

    @property
    def features(self) -> dict[str, Any]:
        return self.data["features"]

    @property
    def quality(self) -> dict[str, Any]:
        return self.data["quality"]

    @property
    def models(self) -> dict[str, Any]:
        return self.data["models"]

    @property
    def validation(self) -> dict[str, Any]:
        return self.data["validation"]

    @property
    def run(self) -> dict[str, Any]:
        return self.data.get("run", {})

    @property
    def pipeline(self) -> dict[str, Any]:
        return self.data.get("pipeline", {})

    @property
    def association(self) -> dict[str, Any]:
        return self.data["quality"]["association"]

    @property
    def quality_rules(self) -> list[dict[str, Any]]:
        return self.data["quality"]["rules"]

    @property
    def feature_cols(self) -> list[str]:
        """Признаки в порядке: сначала числовые, затем категориальные.

        Порядок фиксирован, потому что от него зависит ширина матрицы
        после `ColumnTransformer` и отпечаток схемы (АР-9).
        """
        return list(self.features["numerical"]) + list(self.features["categorical"])

    @property
    def numerical_cols(self) -> list[str]:
        return list(self.features["numerical"])

    @property
    def categorical_cols(self) -> list[str]:
        return list(self.features["categorical"])

    @property
    def target_column(self) -> str:
        return self.data["target"]["column"]

    @property
    def target_name(self) -> str:
        return self.data["target"].get("name", "target")

    @property
    def time_column(self) -> str:
        return self.data["batching"]["time_column"]

    # -- пути ------------------------------------------------------------

    def path(self, key: str) -> Path:
        """Абсолютный путь по ключу из секции `paths`."""
        if key not in self.paths:
            raise ConfigError(f"В секции paths нет ключа {key!r}")
        return self.root / str(self.paths[key])

    @property
    def state_file(self) -> Path:
        return self.path("state_file")

    @property
    def models_dir(self) -> Path:
        return self.path("models")

    @property
    def reports_dir(self) -> Path:
        return self.path("reports")

    @property
    def metadata_dir(self) -> Path:
        return self.path("metadata")

    @property
    def batches_dir(self) -> Path:
        return self.path("data_raw")

    @property
    def rules_file(self) -> Path:
        return self.path("rules_file")

    @property
    def log_file(self) -> Path:
        return self.root / str(self.run.get("log_file", "training.log"))

    def ensure_dirs(self) -> None:
        """Создать каталоги артефактов. Вызывается один раз оркестратором."""
        for key in ("data_raw", "data_processed", "models", "reports", "metadata"):
            if key in self.paths:
                self.path(key).mkdir(parents=True, exist_ok=True)

    # -- идентичность конфигурации ---------------------------------------

    @property
    def config_hash(self) -> str:
        """Короткий стабильный хэш содержимого конфигурации."""
        payload = json.dumps(self.data, sort_keys=True, ensure_ascii=False, default=str)
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]

    def fingerprint(self) -> dict[str, Any]:
        """Сведения о конфигурации для манифеста прогона (АР-6)."""
        return {
            "config_hash": self.config_hash,
            "feature_cols": self.feature_cols,
            "numerical_cols": self.numerical_cols,
            "categorical_cols": self.categorical_cols,
            "target": f"{self.target_column} -> {self.target_name}",
            "validation": self.validation,
        }


# ---------------------------------------------------------------------------
# Загрузка и валидация
# ---------------------------------------------------------------------------


def find_project_root(start: Path | None = None) -> Path:
    """Найти корень проекта — каталог, содержащий `config.yaml`.

    Поиск идёт вверх от точки старта (файл модуля или переданный путь).
    Это избавляет от зависимости от текущего рабочего каталога (D-20).
    """
    candidates = []
    if start is not None:
        candidates.append(Path(start).resolve())
    candidates.append(Path(__file__).resolve().parent.parent)
    candidates.append(Path.cwd().resolve())

    for candidate in candidates:
        for directory in [candidate, *candidate.parents]:
            if (directory / DEFAULT_CONFIG_NAME).is_file():
                return directory
    raise ConfigError(
        f"Не найден {DEFAULT_CONFIG_NAME}. Запускать нужно из корня проекта "
        f"либо передать путь к конфигурации явно."
    )


def load_config(
    path: str | os.PathLike[str] | None = None,
    root: Path | None = None,
) -> Config:
    """Прочитать и провалидировать конфигурацию.

    Args:
        path: путь к YAML-файлу. Если не задан, ищется `config.yaml`
            по алгоритму `find_project_root`.
        root: корень проекта для разрешения относительных путей.
            По умолчанию — каталог с конфигурацией.
    """
    if path is None:
        root = root or find_project_root()
        path = root / DEFAULT_CONFIG_NAME
    else:
        path = Path(path).resolve()
        if root is None:
            root = path.parent

    if not path.is_file():
        raise ConfigError(f"Файл конфигурации не найден: {path}")

    with open(path, "r", encoding="utf-8") as handle:
        raw = yaml.safe_load(handle)

    if not isinstance(raw, dict):
        raise ConfigError(f"Ожидался словарь в верхнем уровне {path}, получен {type(raw).__name__}")

    _validate(raw)
    return Config(data=copy.deepcopy(raw), root=Path(root).resolve())


def _validate(cfg: dict[str, Any]) -> None:
    """Проверить структуру конфигурации, накапливая все ошибки.

    Смысл в том, чтобы пользователь увидел сразу все проблемы, а не
    по одной за прогон.
    """
    errors: list[str] = []

    for section in REQUIRED_SECTIONS:
        if section not in cfg:
            errors.append(f"отсутствует обязательная секция {section!r}")
    if errors:
        raise ConfigError("Некорректная конфигурация:\n  - " + "\n  - ".join(errors))

    _validate_paths(cfg, errors)
    _validate_features(cfg, errors)
    _validate_target(cfg, errors)
    _validate_quality(cfg, errors)
    _validate_validation(cfg, errors)
    _validate_models(cfg, errors)

    if errors:
        raise ConfigError("Некорректная конфигурация:\n  - " + "\n  - ".join(errors))


def _validate_paths(cfg: dict[str, Any], errors: list[str]) -> None:
    required = (
        "data_raw", "models", "reports", "metadata",
        "state_file", "rules_file",
    )
    for key in required:
        if key not in cfg["paths"]:
            errors.append(f"paths.{key} отсутствует")
        elif not str(cfg["paths"][key]).strip():
            errors.append(f"paths.{key} пуст")


def _validate_features(cfg: dict[str, Any], errors: list[str]) -> None:
    features = cfg["features"]
    for key in ("numerical", "categorical"):
        if key not in features:
            errors.append(f"features.{key} отсутствует")
            return
        if not isinstance(features[key], list) or not features[key]:
            errors.append(f"features.{key} должен быть непустым списком")

    numerical = set(features.get("numerical", []))
    categorical = set(features.get("categorical", []))
    overlap = numerical & categorical
    if overlap:
        errors.append(f"признак указан и как числовой, и как категориальный: {sorted(overlap)}")


def _validate_target(cfg: dict[str, Any], errors: list[str]) -> None:
    target = cfg["target"]
    if "column" not in target:
        errors.append("target.column отсутствует")

    features = set(cfg["features"].get("numerical", [])) | set(cfg["features"].get("categorical", []))
    if target.get("column") in features:
        errors.append(
            f"target.column ({target['column']!r}) не должен одновременно быть признаком"
        )

    rule = target.get("positive_rule", "notna")
    if rule not in ("notna", "positive"):
        errors.append(f"target.positive_rule должен быть 'notna' или 'positive', получено {rule!r}")


def _validate_quality(cfg: dict[str, Any], errors: list[str]) -> None:
    quality = cfg["quality"]

    for key in ("rules", "association"):
        if key not in quality:
            errors.append(f"quality.{key} отсутствует")
            return

    for key in ("max_row_missing_ratio", "max_violation_ratio"):
        value = quality.get(key)
        if value is None:
            errors.append(f"quality.{key} отсутствует")
        elif not 0.0 <= float(value) <= 1.0:
            errors.append(f"quality.{key} должен быть в [0, 1], получено {value!r}")

    seen: set[str] = set()
    for index, rule in enumerate(quality["rules"]):
        label = f"quality.rules[{index}]"
        name = rule.get("name")
        if not name:
            errors.append(f"{label}: отсутствует name")
        elif name in seen:
            errors.append(f"{label}: дублирующееся имя {name!r}")
        else:
            seen.add(name)

        severity = rule.get("severity", "error")
        if severity not in SEVERITIES:
            errors.append(f"{label} ({name}): severity должен быть одним из {SEVERITIES}")

        on_missing = rule.get("on_missing", "ignore")
        if on_missing not in ("ignore", "violation"):
            errors.append(
                f"{label} ({name}): on_missing должен быть 'ignore' или 'violation'"
            )

        _validate_rule_condition(rule, label, name, errors, allow_conditional=True)

    assoc = quality["association"]
    for key in ("min_support", "min_confidence"):
        value = assoc.get(key)
        if value is None or not 0.0 <= float(value) <= 1.0:
            errors.append(f"quality.association.{key} должен быть в [0, 1], получено {value!r}")
    n_rules = assoc.get("n_rules")
    if not isinstance(n_rules, int) or n_rules < 1:
        errors.append("quality.association.n_rules должен быть целым >= 1")
    max_len = assoc.get("max_len")
    if max_len is not None and (not isinstance(max_len, int) or max_len < 1):
        errors.append("quality.association.max_len должен быть целым >= 1 или null")
    algorithm = assoc.get("algorithm", "fpgrowth")
    if algorithm not in ("fpgrowth", "apriori"):
        errors.append(
            f"quality.association.algorithm должен быть 'fpgrowth' или 'apriori', получено {algorithm!r}"
        )


def _validate_rule_condition(
    rule: dict[str, Any],
    label: str,
    name: str | None,
    errors: list[str],
    allow_conditional: bool,
) -> None:
    """Проверить тело правила.

    Поддерживаются две формы: одиночное условие (`column`/`op`/`value`)
    и условное правило (`applies_when` + одиночное условие) — например
    «грузоподъёмность должна быть > 0, если тип кузова грузовой».
    """
    if allow_conditional and "applies_when" in rule:
        applies = rule["applies_when"]
        if not isinstance(applies, dict):
            errors.append(f"{label} ({name}): applies_when должен быть словарём")
        else:
            _validate_condition(applies, f"{label} ({name}) applies_when", errors)

    column = rule.get("column")
    if not column:
        errors.append(f"{label} ({name}): отсутствует column")
        return

    op = rule.get("op")
    if op not in VALID_OPERATORS:
        errors.append(
            f"{label} ({name}): op={op!r} недопустим; допустимые: {', '.join(VALID_OPERATORS)}"
        )
        return

    if op in ("between", "not_between"):
        bounds = rule.get("value")
        if not isinstance(bounds, (list, tuple)) or len(bounds) != 2:
            errors.append(f"{label} ({name}): op={op} требует value из двух границ")
        elif float(bounds[0]) >= float(bounds[1]):
            errors.append(f"{label} ({name}): нижняя граница должна быть меньше верхней")
    elif op in ("in", "not_in"):
        if not isinstance(rule.get("value"), (list, tuple)) or not rule["value"]:
            errors.append(f"{label} ({name}): op={op} требует непустой список value")
    elif op not in ("notna", "isna", "positive", "non_negative"):
        if "value" not in rule:
            errors.append(f"{label} ({name}): op={op} требует value")


def _validate_condition(condition: dict[str, Any], label: str, errors: list[str]) -> None:
    """Проверить простое условие без вложенности."""
    if not condition.get("column"):
        errors.append(f"{label}: отсутствует column")
    op = condition.get("op")
    if op not in VALID_OPERATORS:
        errors.append(f"{label}: op={op!r} недопустим")
    elif op in ("in", "not_in") and not condition.get("value"):
        errors.append(f"{label}: op={op} требует непустой список value")
    elif op in ("between", "not_between"):
        bounds = condition.get("value")
        if not isinstance(bounds, (list, tuple)) or len(bounds) != 2:
            errors.append(f"{label}: op={op} требует две границы")


def _validate_validation(cfg: dict[str, Any], errors: list[str]) -> None:
    validation = cfg["validation"]
    strategy = validation.get("strategy", "stream_holdout")
    if strategy not in ("stream_holdout", "holdout"):
        errors.append(
            f"validation.strategy должен быть 'stream_holdout' или 'holdout', получено {strategy!r}"
        )
    test_size = validation.get("test_size")
    if test_size is None or not 0.0 < float(test_size) < 1.0:
        errors.append("validation.test_size должен быть в (0, 1)")


def _validate_models(cfg: dict[str, Any], errors: list[str]) -> None:
    models = cfg["models"]
    for name in ("mlp", "dt"):
        if name not in models:
            errors.append(f"models.{name} отсутствует")
            continue
        if not isinstance(models[name], dict):
            errors.append(f"models.{name} должен быть словарём с гиперпараметрами")

    mlp = models.get("mlp", {})
    if mlp:
        layers = mlp.get("hidden_layer_sizes")
        if not isinstance(layers, (list, tuple)) or not layers:
            errors.append("models.mlp.hidden_layer_sizes должен быть непустым списком")
        elif mlp.get("partial_fit") and mlp.get("warm_start", True):
            # partial_fit игнорирует warm_start: повторный fit перезапустит
            # оптимизацию с нуля. Молча оставлять оба флага — ловушка.
            errors.append(
                "models.mlp: нельзя одновременно partial_fit=true и warm_start=true; "
                "для инкрементального обучения warm_start должен быть false"
            )

"""Декларативные правила качества данных (АР-14).

Заменяет прежнюю схему, где условие правила задавалось строкой
`"lambda df: ..."` и выполнялось через `eval()`. Теперь правило —
это данные, которые можно проверить, показать в отчёте и отличить
друг от друга по намерению.

Главное, что даёт разделение `on_missing`: пропуск в `PREMIUM` — это
неполнота, а пропуск `CARRYING_CAPACITY` у грузовика — настоящее
нарушение. Старый код (сравнение `NaN >= 0` → `False`) смешивал эти
вещи и из-за этого удалял пропуски, объявляя их нарушениями (D-27).

Правило описывает условие, которому строка **должна удовлетворять**.
Если строка условию не удовлетворяет — это нарушение, и всё.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Iterable, Sequence

import numpy as np
import pandas as pd


@dataclass(frozen=True)
class Condition:
    """Простое условие над одной колонкой."""

    column: str
    op: str
    value: Any = None

    def evaluate(self, df: pd.DataFrame) -> pd.Series:
        return evaluate_condition(self.column, self.op, self.value, df)


@dataclass(frozen=True)
class Rule:
    """Правило качества данных.

    Attributes:
        name: идентификатор правила, попадает в метаданные и отчёт.
        column: проверяемая колонка.
        op: оператор из списка `config.VALID_OPERATORS`.
        value: операнд (скаляр, список или пара границ).
        applies_when: необязательное условие применимости. Если задано,
            проверяются только те строки, для которых оно истинно.
        on_missing: как трактовать пропуск в проверяемой колонке —
            `ignore` (пропуск не нарушение) или `violation`
            (пропуск считается нарушением).
        severity: `error` — влияет на очистку; `warn` — только мониторинг.
        description: человекочитаемое пояснение для отчёта.
    """

    name: str
    column: str
    op: str
    value: Any = None
    applies_when: Condition | None = None
    on_missing: str = "ignore"
    severity: str = "error"
    description: str = ""

    @property
    def is_error(self) -> bool:
        return self.severity == "error"

    def applicable_mask(self, df: pd.DataFrame) -> pd.Series:
        """Маска строк, к которым правило вообще применимо."""
        if self.applies_when is None:
            return pd.Series(True, index=df.index)
        return self.applies_when.evaluate(df).fillna(False).astype(bool)

    def holds_mask(self, df: pd.DataFrame) -> pd.Series:
        """Маска строк, удовлетворяющих условию правила."""
        return evaluate_condition(self.column, self.op, self.value, df)

    def violation_mask(self, df: pd.DataFrame) -> pd.Series:
        """Маска строк-нарушений с учётом `applies_when` и `on_missing`."""
        holds = self.holds_mask(df).fillna(False).astype(bool)
        applicable = self.applicable_mask(df)

        # Операторы, предметом которых является сам пропуск, не требуют
        # отдельной обработки отсутствующих значений.
        if self.op in ("notna", "isna"):
            violated = ~holds
        elif self.on_missing == "ignore":
            missing = df[self.column].isna()
            violated = ~holds & ~missing
        else:
            violated = ~holds

        return (violated & applicable).fillna(False).astype(bool)

    def describe(self) -> str:
        """Человекочитаемая формулировка условия для отчёта."""
        if self.description:
            return self.description
        condition = f"{self.column} {_operator_text(self.op)} {_value_text(self.value)}"
        if self.applies_when is not None:
            scope = f"{self.applies_when.column} {_operator_text(self.applies_when.op)} " \
                    f"{_value_text(self.applies_when.value)}"
            return f"{condition}, если {scope}"
        return condition


@dataclass
class RuleSet:
    """Набор правил, построенный из конфигурации."""

    rules: list[Rule] = field(default_factory=list)

    @classmethod
    def from_config(cls, raw_rules: Sequence[dict[str, Any]]) -> "RuleSet":
        rules: list[Rule] = []
        for spec in raw_rules:
            applies_when = None
            if spec.get("applies_when"):
                applies_when = Condition(
                    column=spec["applies_when"]["column"],
                    op=spec["applies_when"]["op"],
                    value=spec["applies_when"].get("value"),
                )
            rules.append(
                Rule(
                    name=spec["name"],
                    column=spec["column"],
                    op=spec["op"],
                    value=spec.get("value"),
                    applies_when=applies_when,
                    on_missing=spec.get("on_missing", "ignore"),
                    severity=spec.get("severity", "error"),
                    description=spec.get("description", ""),
                )
            )
        return cls(rules=rules)

    def __iter__(self):
        return iter(self.rules)

    def __len__(self) -> int:
        return len(self.rules)

    def error_rules(self) -> list[Rule]:
        return [rule for rule in self.rules if rule.is_error]

    def warn_rules(self) -> list[Rule]:
        return [rule for rule in self.rules if not rule.is_error]

    def available(self, df: pd.DataFrame) -> "RuleSet":
        """Отбросить правила, чьи колонки отсутствуют в датафрейме.

        Батч может прийти с неполной схемой; такое правило не должно
        ронять конвейер, но должно быть видно в метаданных как
        «не проверялось».
        """
        kept = [rule for rule in self.rules if _rule_columns_present(rule, df)]
        return RuleSet(rules=kept)

    def missing(self, df: pd.DataFrame) -> list[str]:
        """Имена правил, которые невозможно проверить на этом батче."""
        return [
            rule.name
            for rule in self.rules
            if not _rule_columns_present(rule, df)
        ]


def _rule_columns_present(rule: Rule, df: pd.DataFrame) -> bool:
    if rule.column not in df.columns:
        return False
    if rule.applies_when is not None and rule.applies_when.column not in df.columns:
        return False
    return True


def evaluate_condition(
    column: str,
    op: str,
    value: Any,
    df: pd.DataFrame,
) -> pd.Series:
    """Вычислить булеву маску условия по колонке.

    Все сравнения оборачиваются в `try/except`: неизвестная колонка или
    несовместимые типы не должны прерывать конвейер — вызывающий код
    обрабатывает такие правила через `RuleSet.available()`.
    """
    if column not in df.columns:
        raise KeyError(f"Колонка {column!r} отсутствует в датафрейме")

    series = df[column]

    if op == "notna":
        return series.notna()
    if op == "isna":
        return series.isna()
    if op == "positive":
        return _numeric(series) > 0
    if op == "non_negative":
        return _numeric(series) >= 0
    if op == "eq":
        return _compare(series, value, lambda left, right: left == right)
    if op == "ne":
        return _compare(series, value, lambda left, right: left != right)
    if op == "ge":
        return _compare(series, value, lambda left, right: left >= right)
    if op == "gt":
        return _compare(series, value, lambda left, right: left > right)
    if op == "le":
        return _compare(series, value, lambda left, right: left <= right)
    if op == "lt":
        return _compare(series, value, lambda left, right: left < right)
    if op == "in":
        return series.isin(list(value))
    if op == "not_in":
        return ~series.isin(list(value))
    if op == "between":
        low, high = value
        numeric = _numeric(series)
        return (numeric >= low) & (numeric <= high)
    if op == "not_between":
        low, high = value
        numeric = _numeric(series)
        return ~((numeric >= low) & (numeric <= high))

    raise ValueError(f"Неизвестный оператор правила: {op!r}")


def _numeric(series: pd.Series) -> pd.Series:
    """Числовое представление колонки; нечисловые значения дают NaN.

    Это позволяет корректно применять числовые операторы к колонкам со
    смешанным типом (см. D-26: в `EFFECTIVE_YR` встречается нечисловой мусор).
    """
    if pd.api.types.is_numeric_dtype(series):
        return series
    return pd.to_numeric(series, errors="coerce")


def _compare(series: pd.Series, value: Any, operation) -> pd.Series:
    """Сравнение с приведением к числу, если это уместно."""
    if isinstance(value, (int, float, np.integer, np.floating)):
        return operation(_numeric(series), value)
    return operation(series, value)


def _operator_text(op: str) -> str:
    return {
        "eq": "==", "ne": "!=", "ge": ">=", "gt": ">", "le": "<=", "lt": "<",
        "between": "в диапазоне", "not_between": "вне диапазона",
        "in": "в списке", "not_in": "не в списке",
        "notna": "заполнено", "isna": "пусто",
        "positive": "> 0", "non_negative": ">= 0",
    }.get(op, op)


def _value_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, (list, tuple)):
        return ", ".join(str(item) for item in value)
    return str(value)


# ---------------------------------------------------------------------------
# Применение правил
# ---------------------------------------------------------------------------


def evaluate_rules(
    df: pd.DataFrame,
    rules: Iterable[Rule],
) -> tuple[dict[str, float], dict[str, int]]:
    """Посчитать долю нарушений по каждому правилу.

    Returns:
        (доли нарушений, число нарушенных строк) — обе структуры
        индексированы именами правил.
    """
    ratios: dict[str, float] = {}
    counts: dict[str, int] = {}
    total = max(len(df), 1)

    for rule in rules:
        violations = rule.violation_mask(df)
        count = int(violations.sum())
        counts[rule.name] = count
        ratios[rule.name] = count / total

    return ratios, counts


def clean_by_rules(
    df: pd.DataFrame,
    rules: Iterable[Rule],
    max_violation_ratio: float,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Удалить строки, нарушающие правила с severity=error.

    Правило применяется, только если доля нарушений по нему не превышает
    `max_violation_ratio`. Иначе считается, что правило настроено неверно
    для этих данных: массовое удаление уничтожило бы датасет, поэтому такое
    правило помечается как неприменённое и попадает в отчёт.

    Returns:
        (очищенный датафрейм, отчёт о применении правил).
    """
    report: dict[str, Any] = {
        "rows_in": int(len(df)),
        "rows_out": int(len(df)),
        "applied": [],
        "skipped": [],
        "dropped_by_rule": {},
    }

    result = df
    for rule in rules:
        if not rule.is_error:
            continue
        if not _rule_columns_present(rule, result):
            report["skipped"].append({**rule.describe(), "reason": "колонка отсутствует"})
            continue
        if result.empty:
            break

        violations = rule.violation_mask(result)
        ratio = float(violations.mean())

        if ratio <= max_violation_ratio:
            before = len(result)
            result = result.loc[~violations]
            dropped = before - len(result)
            report["dropped_by_rule"][rule.name] = dropped
            report["applied"].append(
                {
                    "rule": rule.name,
                    "condition": rule.describe(),
                    "violation_ratio": round(ratio, 6),
                    "dropped_rows": dropped,
                }
            )
        else:
            report["skipped"].append(
                {
                    "rule": rule.name,
                    "condition": rule.describe(),
                    "violation_ratio": round(ratio, 6),
                    "reason": (
                        f"доля нарушений {ratio:.4f} превышает порог "
                        f"{max_violation_ratio}; правило не применено"
                    ),
                }
            )

    report["rows_out"] = int(len(result))
    report["rows_removed"] = report["rows_in"] - report["rows_out"]
    return result, report

"""Состояние прогона (АР-4).

`state.json` хранит список батчей, номер последнего обработанного и историю
прогонов. Ключевые свойства:

* **Версионирование схемы.** Поле `schema_version` позволяет отказаться
  читать состояние, записанное несовместимой версией кода.
* **Атомарность.** Запись идёт через временный файл с последующим
  переименованием, поэтому оборванный процесс не оставляет
  наполовину записанный `state.json`.
* **Продвижение только при успехе.** Батч отмечается обработанным лишь
  после того, как конвейер завершился без ошибок (АР-11).

Состояние — единственное, что позволяет инкрементальному режиму
продолжить обработку с места обрыва, в том числе между запусками CI.
"""

from __future__ import annotations

import json
import os
import tempfile
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterator

SCHEMA_VERSION = 2


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


class StateStore:
    """Типобезопасный доступ к состоянию прогона."""

    def __init__(self, path: str | os.PathLike[str]) -> None:
        self.path = Path(path)
        self._state = self._read()

    # -- чтение ----------------------------------------------------------

    def _empty(self) -> dict[str, Any]:
        return {
            "schema_version": SCHEMA_VERSION,
            "created_at": _utc_now(),
            "updated_at": _utc_now(),
            "dataset_hash": None,
            "config_hash": None,
            "batches": [],
            "last_processed": -1,
            "history": [],
            "runs": [],
        }

    def _read(self) -> dict[str, Any]:
        if not self.path.is_file():
            return self._empty()
        try:
            with open(self.path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (json.JSONDecodeError, OSError) as error:
            raise RuntimeError(
                f"Не удалось прочитать состояние {self.path}: {error}. "
                f"Удалите файл, чтобы начать обработку заново."
            ) from error

        version = data.get("schema_version")
        if version != SCHEMA_VERSION:
            raise RuntimeError(
                f"Схема состояния {self.path} не совпадает: "
                f"на диске версия {version}, ожидалась {SCHEMA_VERSION}. "
                f"Перезапустите инициализацию."
            )
        return data

    # -- доступ к полям --------------------------------------------------

    def __getitem__(self, key: str) -> Any:
        return self._state[key]

    @property
    def batches(self) -> list[str]:
        return list(self._state.get("batches", []))

    @property
    def last_processed(self) -> int:
        return int(self._state.get("last_processed", -1))

    @property
    def history(self) -> list[dict[str, Any]]:
        return list(self._state.get("history", []))

    def __len__(self) -> int:
        return len(self.batches)

    def __iter__(self) -> Iterator[str]:
        return iter(self.batches)

    @property
    def is_initialised(self) -> bool:
        return bool(self.batches)

    @property
    def has_next(self) -> bool:
        return self.last_processed + 1 < len(self.batches)

    def remaining(self) -> int:
        return max(len(self.batches) - self.last_processed - 1, 0)

    def next_batch(self) -> tuple[str, int] | None:
        """Путь и индекс следующего необработанного батча."""
        index = self.last_processed + 1
        if index >= len(self.batches):
            return None
        return self.batches[index], index

    # -- запись ----------------------------------------------------------

    def save(self) -> None:
        """Атомарно записать состояние на диск."""
        self._state["updated_at"] = _utc_now()
        self.path.parent.mkdir(parents=True, exist_ok=True)

        # Временный файл в том же каталоге: rename в пределах тома атомарен.
        handle = tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            dir=str(self.path.parent),
            prefix=".state-",
            suffix=".tmp",
            delete=False,
        )
        try:
            with handle:
                json.dump(self._state, handle, ensure_ascii=False, indent=2)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(handle.name, self.path)
        except BaseException:
            Path(handle.name).unlink(missing_ok=True)
            raise

    def init_batches(self, batches: list[str], dataset_hash: str | None = None) -> None:
        """Зафиксировать список батчей и сбросить прогресс обработки."""
        self._state.update(
            {
                "schema_version": SCHEMA_VERSION,
                "created_at": _utc_now(),
                "dataset_hash": dataset_hash,
                "batches": [str(path) for path in batches],
                "last_processed": -1,
                "history": [],
            }
        )
        self.save()

    def mark_processed(
        self,
        index: int,
        *,
        dataset_hash: str | None = None,
        config_hash: str | None = None,
        **details: Any,
    ) -> None:
        """Отметить батч обработанным и записать сведения о запуске."""
        if index < 0 or index >= len(self.batches):
            raise IndexError(
                f"Индекс батча {index} вне диапазона [0, {len(self.batches) - 1}]"
            )
        if index <= self.last_processed:
            return

        entry = {
            "batch_idx": index,
            "batch": self.batches[index],
            "timestamp": _utc_now(),
            **details,
        }
        self._state["last_processed"] = index
        self._state.setdefault("history", []).append(entry)
        if dataset_hash:
            self._state["dataset_hash"] = dataset_hash
        if config_hash:
            self._state["config_hash"] = config_hash
        self.save()

    def record_run(self, **details: Any) -> None:
        """Записать сводку о запуске (используется в манифесте и отчёте)."""
        self._state.setdefault("runs", []).append(
            {"timestamp": _utc_now(), **details}
        )
        self.save()

    def reset(self) -> None:
        """Сбросить прогресс, сохранив список батчей."""
        self._state["last_processed"] = -1
        self._state["history"] = []
        self.save()

"""Накопительное хранилище обучающих данных (АР-8).

Каждая очищенная train-часть батча сохраняется отдельным сжатым файлом
`train_<idx>.csv.gz`. Это даёт три свойства, которых не было в исходной
реализации:

* **Состояние переживает перезапуск.** Пайплайн можно остановить и продолжить
  с того же места, в том числе в CI между запусками.
* **Очистка воспроизводима.** Ставка «дерево переобучается с нуля на всех
  накопленных данных» из `task.md` §4.1 требует именно такого буфера; в
  исходном коде его не было, поэтому дерево обучалось на одном батче (D-3).
* **Прослеживаемость.** По именам файлов видно, какие батчи участвовали
  в обучении, а `stats()` отдаёт эти сведения в метаданные.

В хранилище попадает **только train-часть** батча. Val-часть не
сохраняется никогда — иначе получился бы тот самый случай, когда
оценка производится на данных, участвовавших в обучении (D-2).
"""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any, Sequence

import pandas as pd

_PART_PATTERN = re.compile(r"^train_(\d+)\.csv\.gz$")
_INDEX_NAME = "_index.json"


class TrainingStore:
    """Каталог с накопленными обучающими частями батчей."""

    def __init__(self, path: str | Path, columns: Sequence[str]) -> None:
        self.path = Path(path)
        self.columns = list(columns)
        self.path.mkdir(parents=True, exist_ok=True)

    # -- чтение ----------------------------------------------------------

    def _parts(self) -> list[tuple[int, Path]]:
        found: list[tuple[int, Path]] = []
        for item in self.path.glob("train_*.csv.gz"):
            match = _PART_PATTERN.match(item.name)
            if match:
                found.append((int(match.group(1)), item))
        return sorted(found)

    def __len__(self) -> int:
        return len(self._parts())

    def batch_indices(self) -> list[int]:
        return [index for index, _ in self._parts()]

    def load(self, window: int | None = None) -> pd.DataFrame:
        """Прочитать накопленные данные.

        Args:
            window: если задано, читать только последние `window` батчей.
                По умолчанию — вся история.
        """
        parts = self._parts()
        if window is not None and window > 0:
            parts = parts[-window:]
        if not parts:
            return pd.DataFrame(columns=self.columns)

        frames = [pd.read_csv(item) for _, item in parts]
        combined = pd.concat(frames, ignore_index=True)
        return combined

    # -- запись ----------------------------------------------------------

    def append(self, batch_idx: int, frame: pd.DataFrame) -> int:
        """Дописать train-часть батча. Возвращает число сохранённых строк.

        Повторная запись того же индекса перезаписывает файл: это делает
        конвейер идемпотентным при повторном прогоне одного батча.
        """
        target = self.path / f"train_{batch_idx:04d}.csv.gz"

        if target.exists() and target.stat().st_size > 0:
            # Уже сохранён — не дублируем, но фиксируем актуальный размер.
            return int(len(frame))

        missing = [column for column in self.columns if column not in frame.columns]
        if missing:
            raise KeyError(
                f"В батче {batch_idx} отсутствуют колонки для хранения: {missing}"
            )

        payload = frame[self.columns]
        payload.to_csv(target, index=False, compression="gzip")
        self._write_index()
        return int(len(payload))

    def clear(self) -> None:
        """Удалить все накопленные части (используется при переинициализации)."""
        for _, item in self._parts():
            item.unlink(missing_ok=True)
        self._write_index()

    # -- метаданные ------------------------------------------------------

    def stats(self, window: int | None = None) -> dict[str, Any]:
        """Сведения о содержимом хранилища для метаданных и отчёта."""
        parts = self._parts()
        if window is not None and window > 0:
            parts = parts[-window:]
        return {
            "enabled": True,
            "path": str(self.path),
            "parts": len(parts),
            "batch_indices": [index for index, _ in parts],
            "rows": int(sum(self._row_count(item) for _, item in parts)),
            "columns": self.columns,
        }

    @staticmethod
    def _row_count(path: Path) -> int:
        """Число строк без полного чтения файла."""
        cache = path.parent / _INDEX_NAME
        if cache.is_file():
            try:
                data = json.loads(cache.read_text(encoding="utf-8"))
                if path.name in data:
                    return int(data[path.name])
            except (json.JSONDecodeError, OSError, ValueError):
                pass
        return int(len(pd.read_csv(path)))

    def _write_index(self) -> None:
        """Кэш соответствия «файл → число строк» для быстрых отчётов."""
        index = {item.name: self._count_lines(item) for _, item in self._parts()}
        (self.path / _INDEX_NAME).write_text(
            json.dumps(index, ensure_ascii=False, indent=2), encoding="utf-8"
        )

    @staticmethod
    def _count_lines(path: Path) -> int:
        """Число строк данных в gzip-CSV (минус заголовок)."""
        with pd.read_csv(path, chunksize=50_000) as reader:
            return int(sum(len(chunk) for chunk in reader))

"""Ассоциативные правила (Apriori / FP-tree).

Переписан по результатам baseline-прогона (PLAN.md, §1.8). Исходная
реализация выдавала пять правил с `confidence = 1.0`, и все пять —
в сторону мажоритного класса `INSR_TYPE = 1202` (76 % данных). Причина
методическая: `nlargest(5, 'confidence')` при пороге 0.5 структурно
не может вернуть содержательное правило — максимальная уверенность
достигается именно на частом следствии.

Исправления:

* **D-4 — отбор по `lift`, а не по `confidence`.** Lift показывает, во сколько
  раз правило сильнее случайного совпадения, и потому не «выбирает»
  мажоритный класс. Дополнительно следствия, совпадающие с самым частым
  значением своей колонки, отбрасываются как тривиальные.
* **D-16 — правила хранятся структурно** (`{"column": ..., "value": ...}`),
  а не разбираются из строк вида `"MAKE = AFRO"`. Прежний разбор ломался
  на любом значении, содержащем `=`, и требовал замены подстрок.
* Пороги (`min_support`, `min_confidence`, `min_lift`, `max_len`, `n_rules`)
  и алгоритм перенесены в конфигурацию; по умолчанию `fpgrowth` — задание
  прямо допускает «Apriori / FP-tree», а FP-tree в mlxtend в 3–6 раз быстрее.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Sequence

import pandas as pd
from mlxtend.frequent_patterns import apriori, association_rules, fpgrowth

ALGORITHMS = ("fpgrowth", "apriori")


def _to_transaction_frame(df: pd.DataFrame, columns: Sequence[str]) -> pd.DataFrame:
    """Представить категориальные признаки в виде набора «признак = значение»."""
    present = [column for column in columns if column in df.columns]
    if not present:
        return pd.DataFrame(index=df.index)

    frame = df[present].copy()
    for column in present:
        # Пропуски получают явную метку, чтобы не терять транзакцию.
        frame[column] = frame[column].astype(object).where(
            frame[column].notna(), other="__MISSING__"
        ).astype(str)

    return pd.get_dummies(frame, prefix_sep="=", dtype=bool)


def _majority_values(frame: pd.DataFrame) -> dict[str, str]:
    """Самое частое значение каждой колонки — кандидат на тривиальное следствие."""
    majority: dict[str, str] = {}
    for column in frame.columns:
        counts = frame[column].value_counts()
        if not counts.empty:
            majority[column] = str(counts.index[0])
    return majority


def _item_to_pair(item: str) -> dict[str, str]:
    """Разобрать элемент набора вида `MAKE=AFRO` в пару колонка/значение.

    Разделяем по первому знаку `=`: значение категории может содержать
    `=` (или начинаться с него), и прежняя замена всех вхождений ломала
    такие случаи.
    """
    if "=" not in item:
        return {"column": item, "value": ""}
    column, value = item.split("=", 1)
    return {"column": column, "value": value}


def _label(antecedents: list[dict[str, str]], consequents: list[dict[str, str]]) -> str:
    """Человекочитаемое имя правила для метаданных и отчёта."""
    left = " ∧ ".join(f"{item['column']} = {item['value']}" for item in antecedents)
    right = " ∨ ".join(f"{item['column']} = {item['value']}" for item in consequents)
    return f"{left} → {right}"


def generate_association_rules(
    df: pd.DataFrame,
    categorical_cols: Sequence[str],
    output_path: str | Path,
    *,
    min_support: float = 0.01,
    min_confidence: float = 0.5,
    min_lift: float = 1.2,
    max_len: int | None = 2,
    n_rules: int = 5,
    algorithm: str = "fpgrowth",
    exclude_majority_consequent: bool = True,
) -> list[dict[str, Any]]:
    """Найти ассоциативные правила и сохранить их.

    Args:
        df: батч данных.
        categorical_cols: категориальные признаки для анализа.
        output_path: куда сохранить правила в формате JSON.
        min_support: минимальная поддержка набора.
        min_confidence: минимальная уверенность правила.
        min_lift: минимальный lift — отсекает правила, не сильнее случайных.
        max_len: максимальная длина набора; ограничивает комбинаторный рост.
        n_rules: сколько правил сохранить.
        algorithm: `fpgrowth` или `apriori`.
        exclude_majority_consequent: не сохранять правила, следствие которых
            совпадает с самым частым значением своей колонки.

    Returns:
        Список правил; каждый элемент пригоден для `json.dump` без преобразований.
    """
    if algorithm not in ALGORITHMS:
        raise ValueError(f"Алгоритм должен быть одним из {ALGORITHMS}, получено {algorithm!r}")

    transactions = _to_transaction_frame(df, categorical_cols)
    if transactions.empty or transactions.shape[1] < 2:
        return _persist([], output_path)

    finder = fpgrowth if algorithm == "fpgrowth" else apriori
    itemsets = finder(
        transactions,
        min_support=min_support,
        use_colnames=True,
        **({} if algorithm == "apriori" else {}),
        **({"max_len": max_len} if max_len else {}),
    )

    if itemsets.empty:
        return _persist([], output_path)

    candidates = association_rules(
        itemsets, metric="confidence", min_threshold=min_confidence
    )
    if candidates.empty:
        return _persist([], output_path)

    majority = _majority_values(transactions) if exclude_majority_consequent else {}
    keep: list[dict[str, str]] = []
    for itemset in candidates["consequents"]:
        pair = _item_to_pair(next(iter(itemset)))
        if pair["column"] in majority and pair["value"] == majority[pair["column"]]:
            continue
        keep.append(pair)
    if not keep:
        return _persist([], output_path)

    filtered = candidates.loc[
        candidates["consequents"].apply(lambda itemset: not _is_majority(itemset, majority))
    ]
    if filtered.empty:
        return _persist([], output_path)

    filtered = filtered[filtered["lift"] >= min_lift]
    if filtered.empty:
        return _persist([], output_path)

    # Ранжирование по lift, при равенстве — по уверенности и поддержке.
    ranked = filtered.sort_values(
        by=["lift", "confidence", "support"], ascending=False
    ).head(n_rules)

    rules: list[dict[str, Any]] = []
    for _, row in ranked.iterrows():
        antecedents = [_item_to_pair(item) for item in row["antecedents"]]
        consequents = [_item_to_pair(item) for item in row["consequents"]]
        rules.append(
            {
                "label": _label(antecedents, consequents),
                "antecedents": antecedents,
                "consequents": consequents,
                "support": float(row["support"]),
                "confidence": float(row["confidence"]),
                "lift": float(row["lift"]),
            }
        )

    return _persist(rules, output_path)


def _is_majority(itemset: frozenset, majority: dict[str, str]) -> bool:
    """Следствие целиком совпадает с мажоритным значением своей колонки."""
    for item in itemset:
        pair = _item_to_pair(item)
        if majority.get(pair["column"]) == pair["value"]:
            return True
    return False


def _persist(rules: list[dict[str, Any]], output_path: str | Path) -> list[dict[str, Any]]:
    """Записать правила в JSON. Отсутствие правил — не ошибка."""
    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(rules, handle, ensure_ascii=False, indent=2)
    return rules


def load_association_rules(rules_path: str | Path) -> list[dict[str, Any]]:
    """Прочитать правила; отсутствие файла — пустой список, не ошибка."""
    path = Path(rules_path)
    if not path.is_file():
        return []
    try:
        with open(path, "r", encoding="utf-8") as handle:
            data = json.load(handle)
    except (json.JSONDecodeError, OSError):
        return []
    return data if isinstance(data, list) else []


def rule_statistics(rules: list[dict[str, Any]]) -> dict[str, Any]:
    """Сводка по найденным правилам для метаданных."""
    if not rules:
        return {"n_rules": 0}
    lifts = [rule["lift"] for rule in rules]
    return {
        "n_rules": len(rules),
        "max_lift": round(max(lifts), 4),
        "mean_lift": round(sum(lifts) / len(lifts), 4),
        "mean_confidence": round(sum(rule["confidence"] for rule in rules) / len(rules), 4),
        "mean_support": round(sum(rule["support"] for rule in rules) / len(rules), 6),
    }

