        )
        return {
            "available": True,
            "status": "baseline",
            "note": "эталон дрейфа построен по текущему батчу",
        }

    result = self.drift.check(
        raw.assign(**{target: with_target[target].to_numpy()}),
        target,
        self.config.numerical_cols,
        self.config.categorical_cols,
    )
    self.drift.extend_reference(
        with_target,
        self.config.numerical_cols,
        self.config.categorical_cols,
        target,
