def _apply_fixed_features(frame: pd.DataFrame, names: list[str]) -> pd.DataFrame:
    """Восстановить зафиксированный набор производных признаков.

    Вычисления повторяются по формулам, а не берутся из первого батча:
    иначе на батчах, где не хватает исходной колонки, признак молча
    превратился бы в пустой столбец.
    """
    result = frame.copy()
    for name in names:
        if name in result.columns:
            continue
        if name.startswith("LOG1P_"):
            source = name[len("LOG1P_"):]
            if source in result.columns:
                values = pd.to_numeric(result[source], errors="coerce")
                result[name] = np.log1p(values.clip(lower=0)).astype("float32")
            else:
                result[name] = np.nan
        elif name == "IS_INSURED_VALUE_ZERO" and "INSURED_VALUE" in result.columns:
            values = pd.to_numeric(result["INSURED_VALUE"], errors="coerce")
            result[name] = (values == 0).astype("int8")
        elif name == "IS_CAPACITY_MISSING" and "CARRYING_CAPACITY" in result.columns:
            result[name] = result["CARRYING_CAPACITY"].isna().astype("int8")
        else:
            result[name] = np.nan
    return result

