import glob, json, io, os

import pandas as pd

assert os.path.isdir("data/metadata"), "Run from project root"


def load(prefix):
    out = {}
    for f in glob.glob(f"data/metadata/{prefix}_*.json"):
        try:
            i = int(os.path.basename(f).rsplit("_", 1)[1].split(".")[0])
        except ValueError:
            continue
        out[i] = json.load(open(f, encoding="utf-8"))
    return out


m = load("model_metrics")
mans = load("run_manifest")
idx = sorted(m)

models = sorted(k for k in m[idx[0]] if k not in ("batch_idx", "batch"))
rows = []
for i in idx:
    r = {"batch": i}
    for name in models:
        e = m[i].get(name, {})
        r[f"{name}_f1"] = e.get("f1")
        r[f"{name}_roc"] = e.get("roc_auc")
    rows.append(r)
df = pd.DataFrame(rows)

out = {"batches": len(idx), "models": models}
for name in models:
    out[f"{name}_f1_mean"] = round(df[f"{name}_f1"].mean(), 4)
    out[f"{name}_roc_mean"] = round(df[f"{name}_roc"].mean(), 4)
    out[f"{name}_f1_max"] = round(df[f"{name}_f1"].max(), 4)
    out[f"{name}_f1_min"] = round(df[f"{name}_f1"].min(), 4)
    out[f"{name}_wins"] = int((df[f"{name}_f1"] == df[[f"{x}_f1" for x in models]].max(axis=1)).sum())

last = m[max(idx)]
out["f1_last_batch"] = {k: round(v.get("f1"), 4) for k, v in last.items() if isinstance(v, dict)}

# Реестр
reg = json.load(open("models/registry.json", encoding="utf-8"))
out["registry"] = {
    "n_versions": len(reg["versions"]),
    "production": {
        "model": reg["production"]["model"],
        "version": reg["production"]["version"],
        "f1": round(reg["production"]["metrics"]["f1"], 4),
    } if reg.get("production") else None,
    "statuses": {},
}
for e in reg["versions"]:
    out["registry"]["statuses"][e["status"]] = out["registry"]["statuses"].get(e["status"], 0) + 1

reasons = {}
for e in reg["versions"]:
    for reason in (e.get("gate") or {}).get("reasons", []):
        key = reason.split("=")[0].strip()
        reasons[key] = reasons.get(key, 0) + 1
out["registry"]["rejection_reasons"] = reasons
promoted = [e for e in reg["versions"] if e["status"] in ("production", "previous")]
out["registry"]["promoted_versions"] = [
    {"v": e["version"], "model": e["model"], "f1": round(e["metrics"]["f1"], 4)}
    for e in promoted
]

# Дрейф
drifts = [
    (i, (mans[i].get("drift") or {}).get("max_psi"),
     (mans[i].get("drift") or {}).get("status"))
    for i in idx
]
psi = [d[1] for d in drifts if d[1] is not None]
out["drift"] = {
    "statuses": {},
    "psi_max": round(max(psi), 4) if psi else None,
    "psi_mean": round(sum(psi) / len(psi), 4) if psi else None,
    "psi_first_10": [round(p, 3) for _, p, _ in drifts[:10] if p is not None],
    "psi_last_5": [round(p, 3) for _, p, _ in drifts[-5:] if p is not None],
}
for _, _, s in drifts:
    out["drift"]["statuses"][s] = out["drift"]["statuses"].get(s, 0) + 1

# Признаки
out["features"] = mans[max(idx)].get("features", {})
out["n_features"] = mans[max(idx)].get("preprocessor", {}).get("n_features")

# Интерпретация: топ признаков
expl = mans[max(idx)].get("explanation", {})
out["top_features"] = {}
for name, payload in (expl.get("by_model") or {}).items():
    out["top_features"][name] = [
        (f.get("feature"), f.get("coefficient", f.get("importance")))
        for f in (payload.get("features") or [])[:6]
    ]
out["consensus"] = (expl.get("consensus") or [])[:8]

# EDA
eda = mans[max(idx)].get("drift", {})
q = None
for f in sorted(glob.glob("data/metadata/quality_*.json"))[-1:]:
    q = json.load(open(f, encoding="utf-8"))
if q:
    out["eda_case_inconsistency"] = (q.get("eda") or {}).get("case_inconsistency")
    out["eda_numerical"] = list(((q.get("eda") or {}).get("numerical") or {}).keys())

# Производительность
tot = {}
for i in idx:
    for k, v in (mans[i].get("performance", {}).get("durations") or {}).items():
        tot[k] = tot.get(k, 0.0) + v
out["timings"] = {k: round(v, 2) for k, v in sorted(tot.items(), key=lambda p: -p[1])}
mem = [mans[i].get("performance", {}).get("peak_rss_mb") for i in idx
       if mans[i].get("performance", {}).get("peak_rss_mb")]
out["peak_rss_mb"] = max(mem) if mem else None
out["stored_rows"] = mans[max(idx)].get("training_store", {}).get("rows")

with io.open(r"C:\Users\Zarip\AppData\Local\Temp\opencode\wave2.json", "w", encoding="utf-8") as fh:
    json.dump(out, fh, ensure_ascii=False, indent=2)
print("written")

