def _categorical_psi(reference: dict[str, float], actual: dict[str, float], epsilon: float = 1e-6) -> float:
    """PSI для категориального распределения по объединённым категориям."""
    keys = set(reference) | set(actual)
    if not keys:
        return float("nan")

    total = 0.0
    for key in keys:
        expected = max(float(reference.get(key, 0.0)), epsilon)
        observed = max(float(actual.get(key, 0.0)), epsilon)
        total += (observed - expected) * np.log(observed / expected)
    return float(total)

