import glob, json, io, os, collections, statistics as S

import pandas as pd

assert os.path.isdir("data/metadata"), "Run from project root"


def load(prefix):
    out = {}
    for f in glob.glob(f"data/metadata/{prefix}_*.json"):
        try:
            i = int(os.path.basename(f).rsplit("_", 1)[1].split(".")[0])
        except ValueError:
            continue
        out[i] = json.load(open(f, encoding="utf-8"))
    return out


m, mans, q = load("model_metrics"), load("run_manifest"), load("quality")
idx = sorted(m)
models = sorted(k for k in m[idx[0]] if k not in ("batch_idx", "batch"))

rows = []
for i in idx:
    r = {"batch": i}
    for name in models:
        e = m[i].get(name, {})
        r[f"{name}_f1"] = e.get("f1")
        r[f"{name}_roc"] = e.get("roc_auc")
        r[f"{name}_prec"] = e.get("precision")
    rows.append(r)
df = pd.DataFrame(rows)
f1cols = [f"{x}_f1" for x in models]

out = {"batches": len(idx), "models": models}
for name in models:
    out[f"{name}_f1_mean"] = round(df[f"{name}_f1"].mean(), 4)
    out[f"{name}_roc_mean"] = round(df[f"{name}_roc"].mean(), 4)
    out[f"{name}_prec_mean"] = round(df[f"{name}_prec"].mean(), 4)
    out[f"{name}_wins"] = int((df[f"{name}_f1"] == df[f1cols].max(axis=1)).sum())

# Реестр
reg = json.load(open("models/registry.json", encoding="utf-8"))
statuses = collections.Counter(e["status"] for e in reg["versions"])
reason_kinds = collections.Counter()
for e in reg["versions"]:
    for reason in (e.get("gate") or {}).get("reasons", []):
        if "PSI" in reason:
            reason_kinds["PSI"] += 1
        elif "f1 упал" in reason:
            reason_kinds["регрессия f1"] += 1
        elif "ниже порога" in reason:
            reason_kinds["ниже min_f1"] += 1
        else:
            reason_kinds[reason[:20]] += 1
out["registry"] = {
    "n_versions": len(reg["versions"]),
    "statuses": dict(statuses),
    "reason_kinds": dict(reason_kinds),
    "production": {
        "model": reg["production"]["model"],
        "version": reg["production"]["version"],
        "batch": reg["production"]["batch_idx"],
        "f1": round(reg["production"]["metrics"]["f1"], 4),
    } if reg.get("production") else None,
    "promoted": [
        {"v": e["version"], "m": e["model"], "b": e["batch_idx"],
         "f1": round(e["metrics"]["f1"], 4)}
        for e in reg["versions"] if e["status"] in ("production", "previous")
    ],
}

# Дрейф
st = collections.Counter()
psis, kss, tgt_psis, tgt_rel = [], [], [], []
for i in idx:
    dr = mans[i].get("drift", {})
    st[dr.get("status")] += 1
    if dr.get("max_psi") is not None:
        psis.append(dr["max_psi"])
    if dr.get("max_ks") is not None:
        kss.append(dr["max_ks"])
    t = dr.get("target") or {}
    if t.get("psi") is not None:
        tgt_psis.append((i, t["psi"]))
    if t.get("relative_change") is not None:
        tgt_rel.append((i, t["relative_change"]))

out["drift"] = {
    "statuses": dict(st),
    "psi": {"mean": round(S.mean(psis), 3), "median": round(S.median(psis), 3),
            "min": round(min(psis), 3), "max": round(max(psis), 3)},
    "ks": {"mean": round(S.mean(kss), 3), "max": round(max(kss), 3)},
    "target_psi_last": round(tgt_psis[-1][1], 4) if tgt_psis else None,
    "target_psi_max": round(max(p for _, p in tgt_psis), 4) if tgt_psis else None,
    "target_rel_change_last": tgt_rel[-1][1] if tgt_rel else None,
    "target_rel_change_min": min(r for _, r in tgt_rel) if tgt_rel else None,
}

# Признаки и качество
out["features"] = mans[max(idx)]["features"]
out["n_features"] = mans[max(idx)]["preprocessor"]["n_features"]
eda = (q[max(idx)].get("eda") or {})
out["eda_case_inconsistency"] = eda.get("case_inconsistency")
out["eda_sentinel_zeros"] = {
    k: v.get("zeros_ratio") for k, v in (eda.get("numerical") or {}).items()
    if v.get("zeros_ratio", 0) > 0.05
}
out["timeliness"] = q[max(idx)]["timeliness"]

# Ассоциативные правила
rules = json.load(open("data/rules.json", encoding="utf-8"))
out["rules"] = [
