out["timings"] = {k: round(v, 1) for k, v in sorted(tot.items(), key=lambda p: -p[1])}
mem = [mans[i].get("performance", {}).get("peak_rss_mb") for i in idx
       if mans[i].get("performance", {}).get("peak_rss_mb")]
out["peak_rss_mb"] = max(mem) if mem else None
out["stored_rows"] = mans[max(idx)]["training_store"]["rows"]

