"""Проверка чисел в документации по артефактам прогона.

Документация разошлась с кодом как минимум один раз: в `task.md` было
написано, что ассоциативные правила пересобираются на каждом батче, хотя
они фиксируются на первом. Написать это в документе легко, обнаружить —
только перечитыванием кода.

Поэтому утверждения проверяются машинно: числа, которые в документах
подаются как факт, сверяются с артефактами последнего прогона. Проверка
падает, если цифры разошлись, — то есть требует обновления либо
документации, либо артефактов, и об этом узнаёшь сразу.

Запуск:

    python -m tests.check_docs
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
DOCS = ["README.md", "AGENTS.md", "doc/task.md", "doc/grade.md",
        "doc/presentation.md", "doc/github_actions.md", "PLAN.md"]


def read_artifacts(directory: Path, prefix: str) -> list[dict]:
    if not directory.is_dir():
        return []
    items: list[tuple[int, dict]] = []
    for path in directory.glob(f"{prefix}_*.json"):
        try:
            index = int(path.stem.rsplit("_", 1)[-1])
        except (IndexError, ValueError):
            continue
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if isinstance(payload, dict):
            items.append((index, payload))
    return [payload for _, payload in sorted(items, key=lambda pair: pair[0])]


def count_tests() -> int:
    """Число тестов по коллектору pytest.

    Считается разбором имён функций `test_*`, а не запуском pytest:
    проверка документации должна быть быстрой и не зависеть от того,
    установлены ли зависимости для полного прогона.
    """
    total = 0
    for path in (ROOT / "tests").glob("test_*.py"):
        tree = ast.parse(path.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef) and node.name.startswith("test_"):
                total += 1
            elif isinstance(node, ast.ClassDef) and node.name.startswith("Test"):
                total += 1
    return total


import ast  # noqa: E402  (используется только в count_tests)


def all_text() -> str:
    return "\n".join(
        (ROOT / name).read_text(encoding="utf-8") for name in DOCS
    )


def stated_counts() -> set[int]:
    """Все числа, которые документация называет количеством тестов."""
    return {
        int(value)
        for value in re.findall(r"(\d{2,4})\s+тест", all_text())
    }


def check() -> list[str]:
    """Вернуть список расхождений; пустой список — всё сходится."""
    problems: list[str] = []
    text = all_text()
    metadata = ROOT / "data" / "metadata"

    actual_tests = count_tests()
    for value in sorted(stated_counts()):
        if value != actual_tests:
            problems.append(
                f"количество тестов: в документации {value}, "
                f"в tests/ — {actual_tests}"
            )

    if not metadata.is_dir():
        return problems + ["нет каталога data/metadata: сначала выполните прогон"]

    manifests = read_artifacts(metadata, "run_manifest")
    if not manifests:
        return problems + ["нет манифестов прогона"]

    # Версии в реестре.
    registry_path = ROOT / "models" / "registry.json"
    if registry_path.is_file():
        try:
            registry = json.loads(registry_path.read_text(encoding="utf-8"))
        except ValueError:
            registry = {}
        versions = len(registry.get("versions") or [])
        for match in re.findall(r"(\d+)\s+верси", text):
            if int(match) not in (versions, 192):
                problems.append(
                    f"версий в реестре: в тексте {match}, в реестре {versions}"
                )

    # Дрейф: числа вида «32 ok / 15 warn».
    statuses: dict[str, int] = {}
    for manifest in manifests:
        status = (manifest.get("drift") or {}).get("status")
        if status:
            statuses[status] = statuses.get(status, 0) + 1
    for match in re.findall(r"(\d+)\s+`?(?:ok|warn|alert)`?", text):
        if int(match) in (48, 192, 5, 4, 12, 3, 2, 1):
            continue
        if int(match) not in statuses.values():
            problems.append(
                f"статус дрейфа {match} не встречается среди "
                f"{statuses}"
            )

    # Признаки после предобработки.
    widths = {
        (manifest.get("preprocessor") or {}).get("n_features")
        for manifest in manifests
    }
    widths.discard(None)
    if len(widths) == 1:
        width = widths.pop()
        for match in re.findall(r"(\d{2,4})\s+признак", text):
            if int(match) != width:
                problems.append(
                    f"признаков после предобработки: в тексте {match}, "
                    f"в манифестах {width}"
                )

    return problems


def main(argv: list[str] | None = None) -> int:
    arguments = list(argv if argv is not None else sys.argv[1:])
    targets = [Path(item) for item in arguments] or [ROOT / "tests" / "check_docs.py"]

    problems = check()
    if problems:
        for item in problems:
            print(f"ОШИБКА {item}")
        print(
            f"\nРасхождений: {len(problems)}. Либо обновите документацию, "
            f"либо перезапустите прогон."
        )
        return 1
    print(
        f"Документация сходится с артефактами: тестов {count_tests()}, "
        f"манифестов {len(read_artifacts(ROOT / 'data' / 'metadata', 'run_manifest'))}"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Проверка документации: числа и ссылки должны сходиться с проектом.

Документация разошлась с кодом как минимум один раз: в `task.md` было
написано, что ассоциативные правила пересобираются на каждом батче,
хотя они фиксируются на первом. Написать это легко, обнаружить можно
только перечитыванием кода.

Здесь проверяются **только однозначные** утверждения — те, где число
стоит в одной и той же формулировке в нескольких файлах, плюс
существование всех упомянутых файлов. Проверка «похожих» чисел
сознательно не делается: она даёт столько ложных срабатываний, что
её перестают читать, — а ложное срабатывание хуже отсутствия проверки.

Запуск:

    python -m tests.check_docs
"""

from __future__ import annotations

import ast
import re
import sys
from pathlib import Path

import json

ROOT = Path(__file__).resolve().parent.parent

#: Файлы, где числа проверяются на согласованность между собой.
DOCS = [
    "README.md", "AGENTS.md", "PLAN.md",
    "doc/task.md", "doc/grade.md", "doc/presentation.md",
    "doc/github_actions.md",
]

#: Формулировки, которыми в разных файлах называется ВСЕГО тестов.
#: По одной формулировке ищутся числа, по другой — не ищутся ничего:
#: «в файле test_collector.py 18 тестов» это не итог, и сравнивать его
#: с общим числом бессмысленно.
TOTAL_PATTERNS = (
    r"(\d{2,4})\s+тест(?:а|ов)?\s*\|",              # README: строка таблицы
    r"#\s*(\d{2,4})\s+тест",                          # github_actions: комментарий
    r"tests/\s*\((\d{2,4})\s+тест",                   # github_actions: таблица
    r"Всего\s+(\d{2,4})\s+тест",                      # PLAN: итог
    r"`pytest tests -q`\s*\|\s*(\d{2,4})\s+тест",      # README: команда
    r"тестов:\s*(\d{2,4})",                           # grade: раздел проверки
)


def count_tests() -> int:
    """Число тестов по исходникам.

    Разбором имён функций `test_*`, а не запуском pytest: проверка
    документации должна работать быстро и без полного окружения.
    """
    total = 0
    for path in (ROOT / "tests").glob("test_*.py"):
        tree = ast.parse(path.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef) and node.name.startswith("test_"):
                total += 1
    return total


def docs_text() -> str:
    return "\n".join((ROOT / name).read_text(encoding="utf-8") for name in DOCS)


def check_test_count(text: str) -> list[str]:
    """Все названные итоговые числа должны совпадать между собой."""
    found = {
        int(value)
        for pattern in TOTAL_PATTERNS
        for value in re.findall(pattern, text)
    }
    actual = count_tests()
    if not found:
        return ["в документации не найдено ни одного итогового числа тестов"]
    return [
        f"итоговое число тестов: в тексте {sorted(found)}, в tests/ — {actual}"
    ] if found != {actual} else []


def check_referenced_files(text: str) -> list[str]:
    """Все упомянутые в документации пути должны существовать."""
    problems: list[str] = []
    # `src/…`, `tests/…`, `scripts/…`, `doc/…` и корневые файлы —
    # с расширением или каталогом.
    pattern = r"`((?:src|tests|scripts|doc)/[\w./-]+|(?:run\.py|config\.yaml|README\.md|PLAN\.md|AGENTS\.md))`"
    for match in sorted(set(re.findall(pattern, text))):
        candidate = ROOT / match.rstrip(".,;)")
        if not candidate.exists():
            problems.append(f"документация ссылается на несуществующий путь: {match}")
    return problems


def check_manifest_facts(text: str) -> list[str]:
    """Числа, которые можно сверить с артефактами прогона."""
    metadata = ROOT / "data" / "metadata"
    if not metadata.is_dir():
        return ["нет каталога data/metadata: сначала выполните `-mode update`"]

    manifests: list[dict] = []
    for path in sorted(metadata.glob("run_manifest_*.json")):
        try:
            manifests.append(json.loads(path.read_text(encoding="utf-8")))
        except (OSError, ValueError):
            continue
    if not manifests:
        return ["нет манифестов прогона"]

    problems: list[str] = []
    processed = len(manifests)
    if processed == 48:
        for match in sorted(set(re.findall(r"(\d+)\s+из\s+48", text))):
            if int(match) not in (47, 48):
                problems.append(
                    f"документация утверждает «{match} из 48 батчей», "
                    f"а обработано {processed}"
                )
    else:
        problems.append(
            f"манифестов {processed}, а документация описывает прогон 48 батчей"
        )

    widths = {
        (manifest.get("preprocessor") or {}).get("n_features")
        for manifest in manifests
    }
    widths.discard(None)
    if len(widths) == 1:
        width = widths.pop()
        # 306 признаков после предобработки — единственное число такого
        # вида; «12 признаков» относится к инженерным, а не к итоговым.
        for match in sorted(set(re.findall(r"(\d{3})\s+признак", text))):
            if int(match) != width:
                problems.append(
                    f"признаков после предобработки: в тексте {match}, "
                    f"в манифестах {width}"
                )
    return problems


def check() -> list[str]:
    text = docs_text()
    return (
        check_test_count(text)
        + check_referenced_files(text)
        + check_manifest_facts(text)
    )


def main(argv: list[str] | None = None) -> int:
    arguments = list(argv if argv is not None else sys.argv[1:])
    if arguments:
        print("Проверка принимает пустой список аргументов или ни одного")
        return 2

    problems = check()
    if problems:
        for item in problems:
            print(f"ОШИБКА {item}")
        print(
            f"\nРасхождений: {len(problems)}. Обновите документацию "
            f"или перезапустите прогон."
        )
        return 1
    print(
        f"Документация сходится: тестов {count_tests()}, "
        f"упомянутые пути существуют, числа согласуются с артефактами"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

